<script setup lang="ts">
import { PhArchive, PhArrowDown, PhArrowLeft, PhArrowUp, PhArrowUpRight, PhCheck, PhClockCounterClockwise, PhFunnel, PhHouse, PhJar, PhMagnifyingGlass, PhMinus, PhPlus, PhSnowflake, PhStack, PhX } from '@phosphor-icons/vue';
import { addBatch, addProduct, categories, demoPantry, emptyPantry, locations, moveStock, productStock, stock, units, type Category, type Location, type Product, type Unit } from '../src/domain/pantry';
const { state, ready, busy, error, mutate } = usePantry();
const view = ref<'inventory' | 'history'>('inventory');
const search = ref(''); const category = ref('Todas'); const location = ref('Todas'); const stockFilter = ref('Todos');
const modal = ref<'product' | 'batch' | 'movement' | 'detail' | 'reset' | null>(null);
const dialog = ref<HTMLDialogElement>(); const selectedId = ref(''); const notice = ref(''); const formError = ref('');
const form = reactive({ name: '', category: 'Conservas' as Category, unit: 'botes' as Unit, quantity: 1, label: '', location: 'Despensa' as Location, date: '', notes: '', batchId: '', movement: 'entrada' as 'entrada' | 'consumo' | 'ajuste', reason: '' });
const selected = computed(() => state.value.products.find(p => p.id === selectedId.value));
const batches = computed(() => state.value.batches.filter(b => b.productId === selectedId.value));
const availableBatches = computed(() => batches.value.filter(b => form.movement !== 'consumo' || stock(state.value, b.id) > 0));
const selectedBatch = computed(() => state.value.batches.find(b => b.id === form.batchId));
const currentStock = computed(() => selectedBatch.value ? stock(state.value, selectedBatch.value.id) : 0);
const normalize = (text: string) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const visibleProducts = computed(() => state.value.products.filter(p => {
  const productBatches = state.value.batches.filter(b => b.productId === p.id);
  return normalize(p.name).includes(normalize(search.value)) && (category.value === 'Todas' || p.category === category.value) && (location.value === 'Todas' || productBatches.some(b => b.location === location.value && stock(state.value, b.id) > 0)) && (stockFilter.value === 'Todos' || (stockFilter.value === 'Con existencias' ? productStock(state.value, p.id) > 0 : productStock(state.value, p.id) === 0));
}).sort((a,b) => a.name.localeCompare(b.name, 'es')));
const activeBatches = computed(() => state.value.batches.filter(b => stock(state.value, b.id) > 0));
const activeLocations = computed(() => new Set(activeBatches.value.map(b => b.location)).size);
const history = computed(() => state.value.movements.map(m => { const batch = state.value.batches.find(b => b.id === m.batchId)!; return { ...m, batch, product: state.value.products.find(p => p.id === batch.productId)! }; }).filter(m => normalize(m.product.name + ' ' + m.batch.label).includes(normalize(search.value))));
const modalTitle = computed(() => ({ product: 'Un producto nuevo', batch: 'Añadir un lote', movement: form.movement === 'entrada' ? 'Añadir existencias' : form.movement === 'consumo' ? 'Registrar consumo' : 'Corregir recuento', detail: selected.value?.name || 'Producto', reset: 'Empezar mi despensa' })[modal.value || 'product']);
function closeModal() { if (!busy.value) modal.value = null; }
watch(modal, async value => { await nextTick(); if (value && !dialog.value?.open) { dialog.value?.showModal(); dialog.value?.querySelector<HTMLInputElement>('input:not([type="hidden"])')?.focus(); } else if (!value && dialog.value?.open) dialog.value.close(); });
function resetForm() { Object.assign(form, { name: '', category: 'Conservas', unit: 'botes', quantity: 1, label: '', location: 'Despensa', date: '', notes: '', batchId: '', movement: 'entrada', reason: '' }); formError.value = ''; }
function openProduct() { resetForm(); form.quantity = 0; modal.value = 'product'; }
function openBatch(product: Product) { resetForm(); selectedId.value = product.id; modal.value = 'batch'; }
function openMovement(product: Product, type: 'entrada' | 'consumo' | 'ajuste', batchId?: string) {
  resetForm(); selectedId.value = product.id; form.movement = type;
  const list = state.value.batches.filter(b => b.productId === product.id && (type !== 'consumo' || stock(state.value,b.id) > 0));
  if (!list.length) { openBatch(product); return; }
  form.batchId = batchId || list[0]!.id; if(type === 'ajuste') form.quantity = stock(state.value,form.batchId); modal.value = 'movement';
}
function showDetail(product: Product) { selectedId.value = product.id; formError.value = ''; modal.value = 'detail'; }
function dateLabel(value: string) { return value ? new Intl.DateTimeFormat('es', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value + 'T12:00:00')) : 'Sin fecha'; }
function timeLabel(value: string) { return new Intl.DateTimeFormat('es', { day:'numeric',month:'short',hour:'2-digit',minute:'2-digit' }).format(new Date(value)); }
function productLocations(id: string) { return [...new Set(state.value.batches.filter(b=>b.productId===id&&stock(state.value,b.id)>0).map(b=>b.location))].join(' · ') || 'Sin existencias'; }
async function save() {
  formError.value = ''; let ok = false;
  if (modal.value === 'product') ok = await mutate(current => { let next = addProduct(current, form); if (form.quantity > 0) next = addBatch(next, next.products.at(-1)!.id, form); else if (!Number.isSafeInteger(form.quantity) || form.quantity !== 0) throw new Error('Introduce una cantidad entera válida.'); return next; });
  else if (modal.value === 'batch') ok = await mutate(current => addBatch(current, selectedId.value, form));
  else if (modal.value === 'movement') ok = await mutate(current => moveStock(current, form.batchId, form.movement, form.quantity, form.reason));
  else if (modal.value === 'reset') ok = await mutate(current => { if (!current.demo) throw new Error('Esta despensa ya no es de ejemplo. No se han borrado sus datos.'); return emptyPantry(); });
  if(ok) { notice.value = modal.value === 'reset' ? 'Tu despensa está lista para empezar.' : 'Cambio guardado en tu despensa.'; modal.value = null; } else formError.value = error.value;
}
async function loadDemo() { const ok = await mutate(current => { if(current.products.length) throw new Error('La despensa debe estar vacía para cargar el ejemplo.'); return demoPantry(); }); if(ok) notice.value='Ejemplo cargado. Puedes probar todas las acciones.'; }
function clearFilters() { search.value='';category.value='Todas';location.value='Todas';stockFilter.value='Todos'; }
</script>

<template>
  <div class="app-layout">
    <a class="skip-link" href="#main">Saltar al contenido</a>
    <aside class="sidebar">
      <a href="#main" class="brand" aria-label="Rebost, inicio" @click="view='inventory'"><span class="brand-symbol">r<span>.</span></span><span>rebost<span class="brand-caption">un lugar para lo que guardas</span></span></a>
      <div class="pantry-switch"><span class="pantry-avatar"><PhHouse :size="20" /></span><div><strong>Mi despensa</strong><span>Tu espacio en casa</span></div></div>
      <nav aria-label="Navegación principal" class="side-nav"><button :aria-current="view==='inventory'?'page':undefined" @click="view='inventory';search=''" type="button"><PhArchive :size="21" />Mi despensa<span class="nav-count">{{ state.products.length }}</span></button><button :aria-current="view==='history'?'page':undefined" @click="view='history';search=''" type="button"><PhClockCounterClockwise :size="21" />Movimientos</button></nav>
      <div class="sidebar-note"><span class="tiny-label">MENOS OLVIDOS, MÁS APROVECHAR</span><p>Cada bote cuenta.<br />Y cada pequeña reserva, también.</p><PhJar :size="42" weight="duotone" /></div>
      <div class="local-indicator"><span class="local-dot" />Guardado en este navegador</div>
    </aside>
    <div class="main-column">
      <header class="topbar"><p><PhHouse :size="16" />Mi despensa<span>/</span>{{ view==='inventory'?'Inventario':'Movimientos' }}</p><span class="local-badge">Primera versión · Local</span></header>
      <main id="main" class="page-shell">
        <div class="page-heading"><div><p class="eyebrow">UN POCO DE ORDEN, MUCHA TRANQUILIDAD</p><h1>{{ view==='inventory'?'Lo que tienes, a mano.':'Cada cambio, en su sitio.' }}</h1><p class="page-intro">{{ view==='inventory'?'Tus conservas, fermentados y básicos. Sabe qué queda y sigue disfrutándolo.':'Una pequeña memoria de lo que entra, lo que utilizas y lo que corriges.' }}</p></div><button v-if="view==='inventory'" class="button primary" :disabled="!ready||busy" @click="openProduct"><PhPlus :size="19" />Añadir producto</button></div>
        <div v-if="error" class="alert error" role="alert">{{ error }}</div>
        <div v-if="notice" class="notice" role="status"><PhCheck :size="18" />{{ notice }}<button @click="notice=''" aria-label="Cerrar aviso"><PhX :size="17" /></button></div>
        <div v-if="state.demo" class="demo-banner"><div><strong>Una despensa para probar.</strong><span>Son datos de ejemplo. Añade, consume y descubre cómo funciona.</span></div><button class="text-button" :disabled="busy" @click="modal='reset'">Empezar mi despensa<PhArrowUpRight :size="17" /></button></div>
        <template v-if="view==='inventory'">
          <div class="stats-grid"><article class="stat"><span class="stat-icon"><PhJar :size="24" weight="duotone" /></span><div><strong>{{ state.products.length }}</strong><span>productos en tu despensa</span></div></article><article class="stat"><span class="stat-icon amber"><PhStack :size="24" weight="duotone" /></span><div><strong>{{ activeBatches.length }}</strong><span>lotes con existencias</span></div></article><article class="stat"><span class="stat-icon blue"><PhHouse :size="24" weight="duotone" /></span><div><strong>{{ activeLocations }}</strong><span>ubicaciones con productos</span></div></article></div>
          <div class="inventory-heading"><h2>Tu inventario <span>{{ visibleProducts.length }}</span></h2><label class="search"><PhMagnifyingGlass :size="19" /><input v-model="search" type="search" placeholder="Buscar un producto…" aria-label="Buscar productos" /></label></div>
          <div class="filters"><div class="category-tabs" aria-label="Filtrar por categoría"><button v-for="item in ['Todas',...categories]" :key="item" :aria-pressed="category===item" @click="category=item">{{ item }}</button></div><div class="select-filters"><PhFunnel :size="16" aria-hidden="true" /><select v-model="location" aria-label="Filtrar por ubicación"><option value="Todas">Todas las ubicaciones</option><option v-for="item in locations" :key="item">{{ item }}</option></select><select v-model="stockFilter" aria-label="Filtrar por existencias"><option>Todos</option><option>Con existencias</option><option>Sin existencias</option></select></div></div>
          <div v-if="!ready" class="empty-state"><span class="empty-icon"><PhArchive :size="38" /></span><h3>{{ error?'Tu despensa no está disponible':'Preparando tu despensa…' }}</h3><p>{{ error?'Revisa el aviso de arriba e inténtalo de nuevo.':'Estamos leyendo los datos guardados en este navegador.' }}</p></div>
          <div v-else-if="!state.products.length" class="empty-state"><span class="empty-icon"><PhJar :size="43" weight="duotone" /></span><p class="eyebrow">TODO EMPIEZA CON UN PRIMER BOTE</p><h3>Hagamos sitio a tu despensa.</h3><p>Añade lo que guardas en casa y registra tus lotes.<br />O descubre Rebost con una despensa de ejemplo.</p><div class="empty-actions"><button class="button primary" @click="openProduct"><PhPlus :size="18" />Añadir mi primer producto</button><button class="button secondary" :disabled="busy" @click="loadDemo">Probar con un ejemplo<PhArrowUpRight :size="18" /></button></div></div>
          <div v-else-if="!visibleProducts.length" class="empty-state compact"><PhMagnifyingGlass :size="35" /><h3>No encontramos productos.</h3><p>Prueba con otra búsqueda o cambia los filtros.</p><button class="text-button" @click="clearFilters">Limpiar filtros</button></div>
          <div v-else class="product-grid"><article v-for="product in visibleProducts" :key="product.id" class="product-card"><div class="product-card-top"><span class="product-icon" :class="`category-${categories.indexOf(product.category)}`"><PhJar v-if="product.category==='Conservas'" :size="31" weight="duotone" /><PhSnowflake v-else-if="product.category==='Fermentados'" :size="31" weight="duotone" /><PhArchive v-else :size="31" weight="duotone" /></span><span class="category-label">{{ product.category }}</span></div><button class="product-title" @click="showDetail(product)">{{ product.name }}<PhArrowUpRight :size="17" /></button><p class="product-location"><PhHouse :size="14" />{{ productLocations(product.id) }}</p><div class="stock-line"><p><strong>{{ productStock(state,product.id) }}</strong> {{ product.unit }}</p><span>{{ state.batches.filter(b=>b.productId===product.id&&stock(state,b.id)>0).length }} lotes activos</span></div><div class="card-actions"><button :disabled="busy" @click="openMovement(product,'entrada')"><PhPlus :size="17" />Añadir</button><button :disabled="busy||productStock(state,product.id)===0" @click="openMovement(product,'consumo')"><PhMinus :size="17" />Consumir</button></div></article><button class="add-card" @click="openProduct"><span><PhPlus :size="25" /></span><strong>Algo más para guardar</strong><span>Añade otro producto a tu despensa</span></button></div>
          <p v-if="state.products.length" class="inventory-note"><PhClockCounterClockwise :size="16" />Cada entrada y consumo queda guardado en tus movimientos.</p>
        </template>
        <template v-else><div class="inventory-heading"><h2>Historial <span>{{ history.length }}</span></h2><label class="search"><PhMagnifyingGlass :size="19" /><input v-model="search" type="search" placeholder="Buscar producto o lote…" aria-label="Buscar movimientos" /></label></div><div v-if="!history.length" class="empty-state"><PhClockCounterClockwise :size="40" /><h3>{{ search?'No hay coincidencias.':'Aquí empieza la historia de tu despensa.' }}</h3><p>Las entradas, consumos y correcciones aparecerán aquí.</p></div><ol v-else class="history-list"><li v-for="movement in history" :key="movement.id"><span class="movement-icon" :class="movement.type"><PhArrowDown v-if="movement.delta>0" :size="21" /><PhArrowUp v-else :size="21" /></span><div class="movement-description"><strong>{{ movement.product.name }}</strong><p>{{ movement.batch.label }} · {{ movement.batch.location }}</p><span v-if="movement.note">{{ movement.note }}</span></div><div class="movement-meta"><strong :class="movement.delta>0?'positive':'negative'">{{ movement.delta>0?'+':'' }}{{ movement.delta }} {{ movement.product.unit }}</strong><span>{{ movement.type==='entrada'?'Entrada':movement.type==='consumo'?'Consumo':'Corrección' }} · {{ timeLabel(movement.createdAt) }}</span></div></li></ol></template>
        <footer class="page-footer"><span>rebost<span class="footer-dot">.</span> <span>Un lugar para lo que guardas.</span></span><p>Datos solo en este navegador. Sin cuenta ni sincronización.</p></footer>
      </main>
    </div>

    <dialog ref="dialog" class="modal" aria-labelledby="modal-title" @cancel.prevent="closeModal" @close="modal=null">
      <div class="modal-header"><div><p class="eyebrow">{{ modal==='detail'?'TU PRODUCTO':'MI DESPENSA' }}</p><h2 id="modal-title">{{ modalTitle }}</h2></div><button class="icon-button" type="button" :disabled="busy" aria-label="Cerrar ventana" @click="closeModal"><PhX :size="23" /></button></div>
      <template v-if="modal==='detail'&&selected"><div class="detail-summary"><span>{{ selected.category }} · {{ selected.unit }}</span><strong>{{ productStock(state,selected.id) }} <small>{{ selected.unit }}</small></strong></div><div class="detail-heading"><h3>Lotes</h3><button class="text-button" @click="openBatch(selected)"><PhPlus :size="17" />Nuevo lote</button></div><p v-if="!batches.length" class="help-text">Aún no hay lotes. Añade el primero para registrar existencias.</p><article v-for="batch in batches" :key="batch.id" class="batch-card"><div class="batch-heading"><h4>{{ batch.label }}</h4><strong>{{ stock(state,batch.id) }} {{ selected.unit }}</strong></div><p>{{ batch.location }} · {{ dateLabel(batch.date) }}</p><p v-if="batch.notes" class="batch-notes">{{ batch.notes }}</p><div class="batch-actions"><button class="text-button" @click="openMovement(selected,'entrada',batch.id)">Añadir</button><button class="text-button" :disabled="stock(state,batch.id)===0" @click="openMovement(selected,'consumo',batch.id)">Consumir</button><button class="text-button muted" @click="openMovement(selected,'ajuste',batch.id)">Corregir recuento</button></div></article><p class="help-text">Las fechas son informativas y no garantizan la seguridad de un alimento.</p></template>
      <form v-else-if="modal" @submit.prevent="save"><fieldset :disabled="busy">
        <template v-if="modal==='product'"><label>Nombre del producto<input v-model="form.name" required maxlength="80" placeholder="Ej. Tomate triturado" /></label><div class="form-row"><label>Categoría<select v-model="form.category"><option v-for="item in categories" :key="item">{{ item }}</option></select></label><label>Unidad<select v-model="form.unit"><option v-for="item in units" :key="item">{{ item }}</option></select></label></div><label>Cantidad inicial <span class="optional">(puedes empezar con 0)</span><input v-model.number="form.quantity" type="number" required min="0" max="1000000" step="1" inputmode="numeric" /></label></template>
        <template v-if="modal==='batch'||(modal==='product'&&form.quantity>0)"><p v-if="modal==='batch'" class="form-product">{{ selected?.name }}</p><label>Nombre del lote <span class="optional">(opcional)</span><input v-model="form.label" maxlength="80" placeholder="Ej. Tomates de septiembre" /></label><label v-if="modal==='batch'">Cantidad ({{ selected?.unit }})<input v-model.number="form.quantity" type="number" required min="1" max="1000000" step="1" inputmode="numeric" /></label><div class="form-row"><label>Ubicación<select v-model="form.location"><option v-for="item in locations" :key="item">{{ item }}</option></select></label><label>Fecha de elaboración<input v-model="form.date" type="date" /></label></div><label>Notas <span class="optional">(opcional)</span><textarea v-model="form.notes" maxlength="400" rows="3" placeholder="Lo que te gustaría recordar de esta tanda…" /></label></template>
        <template v-if="modal==='movement'"><p class="form-product">{{ selected?.name }}</p><label>Lote<select v-model="form.batchId" required @change="form.movement==='ajuste'&&(form.quantity=currentStock)"><option v-for="batch in availableBatches" :key="batch.id" :value="batch.id">{{ batch.label }} · {{ stock(state,batch.id) }} {{ selected?.unit }} · {{ batch.location }}</option></select></label><p class="stock-hint">Ahora tienes <strong>{{ currentStock }} {{ selected?.unit }}</strong> en este lote.</p><label>{{ form.movement==='ajuste'?'Cantidad real que hay en el lote':form.movement==='consumo'?'¿Cuánto has utilizado?':'¿Cuánto quieres añadir?' }}<input v-model.number="form.quantity" type="number" required :min="form.movement==='ajuste'?0:1" :max="form.movement==='consumo'?currentStock:1000000" step="1" inputmode="numeric" /></label><label>{{ form.movement==='ajuste'?'Motivo de la corrección':'Nota' }}<span v-if="form.movement!=='ajuste'" class="optional"> (opcional)</span><input v-model="form.reason" :required="form.movement==='ajuste'" maxlength="180" :placeholder="form.movement==='ajuste'?'Ej. Recuento manual de la despensa':'Ej. Para la comida de hoy'" /></label><button v-if="form.movement==='entrada'&&selected" type="button" class="text-button" @click="openBatch(selected)"><PhPlus :size="16" />Es una tanda nueva: crear otro lote</button></template>
        <template v-if="modal==='reset'"><p class="body-text">Se eliminarán los productos y movimientos de ejemplo, incluidos los cambios que hayas hecho mientras probabas. Tu despensa quedará vacía para añadir tus propios productos.</p></template>
        <p v-if="formError" class="alert error" role="alert">{{ formError }}</p><div class="form-actions"><button type="button" class="button secondary" @click="closeModal">Cancelar</button><button type="submit" class="button primary">{{ busy?'Guardando…':modal==='reset'?'Empezar desde cero':'Guardar' }}<PhCheck :size="18" /></button></div>
      </fieldset></form>
    </dialog>
  </div>
</template>
